import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- NEW TESTS FOR ISSUE #1 ---

// Use a mock frame to test brick collisions since brick hit logic is in frame()
// we need to export frame or a logic function.
import { frame } from './neon.js';

test('brick bounce: top face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball approaching from below, hitting the top face (y=100)
  // Ball.y + r = 100.01 -> just barely overlapping
  state.ball = { x: 150, y: 100 + 20 + 7 - 0.1, r: 7, vx: 0, vy: UP * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should be destroyed');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy should flip to DOWN');
});

test('brick bounce: bottom face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball approaching from above, hitting the bottom face (y=120)
  state.ball = { x: 150, y: 100 - 7 + 0.1, r: 7, vx: 0, vy: DOWN * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'vy should flip to UP');
});

test('brick bounce: left face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball approaching from left, hitting the left face (x=100)
  state.ball = { x: 100 - 7 - 0.1, y: 110, r: 7, vx: RIGHT * 100, vy: 0 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx should flip to LEFT');
});

test('brick bounce: right face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball approaching from right, hitting the right face (x=200)
  state.ball = { x: 200 + 7 + 0.1, y: 110, r: 7, vx: LEFT * 100, vy: 0 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), RIGHT, 'vx should flip to RIGHT');
});

test('brick bounce: corner hit flips both', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball hitting the top-left corner exactly
  // Penetration x = 7 - (100 - 99) = 6? No.
  // Let's put it so penetrations are equal.
  // Ball center at (100-7+1, 100-7+1) = (94, 94)
  // Brick x=100, y=100. 
  // overlapX = ball.x+r - brick.x = 94+7 - 100 = 1
  // overlapY = ball.y+r - brick.y = 94+7 - 100 = 1
  state.ball = { x: 94, y: 94, r: 7, vx: RIGHT * 100, vy: DOWN * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
});

test('brick bounce: no sticky bounce (push out)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 150, y: 120, r: 7, vx: 0, vy: UP * 100 }; // Ball center at 120, radius 7, bottom of brick is 120.
  // Overlap is from 113 to 127. Ball is at 120.

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  // Ball should be pushed out. If it was at 120 and hit bottom face (y=120), it should be at 120 + 7 = 127.
  assert.ok(state.ball.y >= 127, 'Ball should be pushed out of the brick');
});

test('brick bounce: tunneling prevention (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  // Ball is moving very fast. 
  // Frame 1: y = 90 (above brick)
  // Frame 2: y = 130 (below brick)
  // Brick is from 100 to 120.
  state.ball = { x: 150, y: 90, r: 7, vx: 0, vy: DOWN * 1000 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  // In current implementation, step() moves the ball and then frame() checks collision.
  // We simulate one step and one frame.
  step(state, 0.04); // 1000 * 0.04 = 40px. ball.y becomes 90 + 40 = 130.
  frame(ctx, state);

  assert.equal(brick.alive, false, 'Ball should have hit the brick despite tunneling');
});

