export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    let hit = collides(state.ball, brick);

    // Tunneling prevention: check if ball crossed brick between prev and current position
    if (!hit && state.ball.prevX !== undefined) {
      const bx = brick.x;
      const by = brick.y;
      const bw = brick.w;
      const bh = brick.h;
      const ball = state.ball;

      // Simple sweep: if ball was on one side and is now on the other, it's a hit
      // We approximate by checking if the line segment (prev, current) intersects the brick box
      // For a brick breaker, usually checking if the center crossed the boundaries is enough
      // but let's do a more robust AABB sweep approximation.
      const minX = Math.min(ball.prevX - ball.r, ball.x - ball.r);
      const maxX = Math.max(ball.prevX + ball.r, ball.x + ball.r);
      const minY = Math.min(ball.prevY - ball.r, ball.y + ball.r);
      const maxY = Math.max(ball.prevY + ball.r, ball.y + ball.r);

      if (maxX > bx && minX < bx + bw && maxY > by && minY < by + bh) {
        hit = true;
      }
    }

    if (hit) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Resolve collision face and bounce
      const ball = state.ball;
      const bLeft = brick.x;
      const bRight = brick.x + brick.w;
      const bTop = brick.y;
      const bBottom = brick.y + brick.h;

      const overlapLeft = ball.x + ball.r - bLeft;
      const overlapRight = bRight - (ball.x - ball.r);
      const overlapTop = ball.y + ball.r - bTop;
      const overlapBottom = bBottom - (ball.y - ball.r);

      const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

      if (minOverlap === overlapLeft) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = bLeft - ball.r;
      } else if (minOverlap === overlapRight) {
        ball.vx = Math.abs(ball.vx);
        ball.x = bRight + ball.r;
      } else if (minOverlap === overlapTop) {
        ball.vy = Math.abs(ball.vy);
        ball.y = bTop - ball.r;
      } else if (minOverlap === overlapBottom) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = bBottom + ball.r;
      }
    }

