  // Ball center at 94, 94.
  // overlapLeft = 94+7-100 = 1.
  // overlapTop = 94+7-100 = 1.
  state.ball = { x: 94, y: 94, r: 7, vx: RIGHT * 100, vy: DOWN * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
});

test('brick bounce: no sticky bounce (push out)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 150, y: 120, r: 7, vx: 0, vy: UP * 100 }; 

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.ok(state.ball.y >= 127, 'Ball should be pushed out of the brick');
});

test('brick bounce: tunneling prevention (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  state.ball = { x: 150, y: 90, r: 7, vx: 0, vy: DOWN * 1000 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  step(state, 0.04); // 1000 * 0.04 = 40px. ball.y becomes 90 + 40 = 130.
  frame(ctx, state);

  assert.equal(brick.alive, false, 'Ball should have hit the brick despite tunneling');
});

