import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  frame,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- NEW TESTS FOR ISSUE #1 ---

test('brick bounce: top face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball center is at 100 + 7 + 0.1 = 107.1. Ball top is at 100.1.
  // OverlapTop = 107.1 + 7 - 100 = 14.1
  // OverlapBottom = 120 - (107.1 - 7) = 19.9
  // MinOverlap is Top.
  state.ball = { x: 150, y: 100 + 7 + 0.1, r: 7, vx: 0, vy: UP * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should be destroyed');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy should flip to DOWN');
});

test('brick bounce: bottom face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball center is at 120 - 7 - 0.1 = 112.9. Ball bottom is at 119.9.
  // OverlapBottom = 120 - (112.9 - 7) = 14.1
  // OverlapTop = 112.9 + 7 - 100 = 19.9
  state.ball = { x: 150, y: 120 - 7 - 0.1, r: 7, vx: 0, vy: DOWN * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'vy should flip to UP');
});

test('brick bounce: left face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball center is at 100 - 7 - 0.1 = 92.9. Ball right is at 99.9.
  // OverlapLeft = 92.9 + 7 - 100 = -0.1? No.
  // Let's make it overlap a bit.
  state.ball = { x: 100 - 7 + 0.1, y: 110, r: 7, vx: RIGHT * 100, vy: 0 };
  // overlapLeft = 100.1 + 7 - 100 = 7.1
  // overlapRight = 200 - (100.1 - 7) = 106.9
  // overlapTop = 110 + 7 - 100 = 17
  // overlapBottom = 120 - (110 - 7) = 17

  const ctx = { 
    fillRect: () => { }, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx should flip to LEFT');
});

test('brick bounce: right face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball center is at 200 + 7 - 0.1 = 206.9. Ball left is at 199.9.
  // OverlapRight = 200 - (206.9 - 7) = 0.1.
  state.ball = { x: 200 + 7 - 0.1, y: 110, r: 7, vx: LEFT * 100, vy: 0 };

  const ctx = { 
    fillRect: () => { }, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), RIGHT, 'vx should flip to RIGHT');
});

test('brick bounce: corner hit flips both', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball center at 93, 93.
  // overlapLeft = 93+7-100 = 0.
  // overlapTop = 93+7-100 = 0.
  // overlapRight = 200 - (93-7) = 114.
  // overlapBottom = 120 - (93-7) = 34.
  state.ball = { x: 93, y: 93, r: 7, vx: RIGHT * 100, vy: DOWN * 100 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
});

test('brick bounce: no sticky bounce (push out)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 150, y: 120, r: 7, vx: 0, vy: UP * 100 }; 

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  frame(ctx, state);

  assert.ok(state.ball.y >= 127, 'Ball should be pushed out of the brick');
});

test('brick bounce: tunneling prevention (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  state.ball = { x: 150, y: 90, r: 7, vx: 0, vy: DOWN * 1000 };

  const ctx = { 
    fillRect: () => {}, 
    fillStyle: '', 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {}, 
    font: '' 
  };

  step(state, 0.04); // 1000 * 0.04 = 40px. ball.y becomes 90 + 40 = 130.
  frame(ctx, state);

  assert.equal(brick.alive, false, 'Ball should have hit the brick despite tunneling');
});

